<script setup lang="ts">import { computed } from 'vue'; import { cn } from '@/lib/utils'; const props = withDefaults(defineProps<{ tone?: 'success' | 'warning' | 'destructive' | 'info' | 'neutral'; pulse?: boolean; class?: string }>(), { tone: 'neutral', pulse: false }); const toneClass = computed(() => ({ success: 'bg-success', warning: 'bg-warning', destructive: 'bg-destructive', info: 'bg-primary', neutral: 'bg-muted-foreground' })[props.tone]);</script>
<template><span :class="cn('inline-flex size-2.5 shrink-0 rounded-full', toneClass, pulse && 'animate-pulse', props.class)" /></template>
